/**
 * « Créé par » for derived rows (v0.9.3).
 *
 * A stock movement or a ledger transaction generated by an invoice, a quick
 * sale (VR), a quote conversion, a receipt or a supplier bill carries the name
 * of the person who created that document — never a generic « Système » when
 * the source document knows its author.
 *
 * Resolution order for a row without its own `created_by`:
 *   1. the source invoice / quick sale by id (ledger `notes` = `invoice_id:N|…`)
 *   2. the source document by number (`reference` = FA-…, VR-…, DV-…, receipt or bill number)
 *   3. another stock movement with the same reference that recorded its author
 *      (the document itself may have been deleted since)
 * Unknown stays null; the client then shows its neutral fallback.
 */
import { addColumnIfMissing, schemaOnceForDb } from './schema';

type Row = Record<string, any>;

const clean = (v: unknown): string => (typeof v === 'string' && v.trim() ? v.trim() : '');
const CHUNK = 80;

async function safeAll(db: D1Database, sql: string, binds: unknown[]): Promise<Row[]> {
  try {
    const { results } = await db.prepare(sql).bind(...binds).all();
    return (results || []) as Row[];
  } catch {
    return [];
  }
}

function chunks<T>(list: T[]): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < list.length; i += CHUNK) out.push(list.slice(i, i + CHUNK));
  return out;
}

/** Cache only completed schema work, separately per database. */
async function ensureCreatorColumns(db: D1Database): Promise<void> {
  await schemaOnceForDb(db, 'document_creator_columns', async () => {
    for (const table of ['invoices', 'receipts', 'bills']) {
      try { await addColumnIfMissing(db, table, 'created_by', 'TEXT DEFAULT NULL'); } catch { /* table may not exist yet */ }
    }
    try { await addColumnIfMissing(db, 'expenses', 'created_by', "TEXT DEFAULT ''"); } catch { /* */ }
  });
}

/** Ledger rows written by hand record their author directly. */
export async function ensureExpenseCreatorColumn(db: D1Database): Promise<void> {
  await ensureCreatorColumns(db);
}

/** Creator of each source document, by number and by invoice id. */
export async function creatorsForDocuments(
  db: D1Database,
  numbers: string[],
  invoiceIds: number[] = [],
): Promise<{ byNumber: Map<string, string>; byInvoiceId: Map<number, string> }> {
  await ensureCreatorColumns(db);
  const byNumber = new Map<string, string>();
  const byInvoiceId = new Map<number, string>();
  const nums = [...new Set(numbers.map(clean).filter(Boolean))];
  const ids = [...new Set(invoiceIds.filter((n) => Number.isInteger(n) && n > 0))];

  for (const part of chunks(nums)) {
    const ph = part.map(() => '?').join(', ');
    const put = (rows: Row[]) => {
      for (const r of rows) {
        const who = clean(r.created_by);
        const num = clean(r.number);
        if (who && num && !byNumber.has(num)) byNumber.set(num, who);
      }
    };
    put(await safeAll(db, `SELECT number, created_by FROM invoices WHERE number IN (${ph})`, part));
    put(await safeAll(
      db,
      `SELECT r.number AS number, COALESCE(NULLIF(r.created_by, ''), i.created_by) AS created_by
         FROM receipts r LEFT JOIN invoices i ON i.id = r.invoice_id
        WHERE r.number IN (${ph})`,
      part,
    ));
    put(await safeAll(db, `SELECT number, created_by FROM bills WHERE number IN (${ph})`, part));
  }
  for (const part of chunks(ids)) {
    const ph = part.map(() => '?').join(', ');
    for (const r of await safeAll(db, `SELECT id, created_by FROM invoices WHERE id IN (${ph})`, part)) {
      const who = clean(r.created_by);
      if (who) byInvoiceId.set(Number(r.id), who);
    }
  }
  return { byNumber, byInvoiceId };
}

const invoiceIdFromNotes = (notes: unknown): number | null => {
  const m = /(?:^|\|)invoice_id:(\d+)/.exec(String(notes || ''));
  return m ? Number(m[1]) : null;
};

/** Ledger transactions (expenses table): inherit the source document's creator. */
export async function withLedgerCreators<T extends Row>(db: D1Database, rows: T[]): Promise<Array<T & { created_by: string | null }>> {
  const missing = rows.filter((r) => !clean(r.created_by));
  if (!missing.length) return rows.map((r) => ({ ...r, created_by: clean(r.created_by) || null }));
  const ids = missing.map((r) => invoiceIdFromNotes(r.notes)).filter((n): n is number => n != null);
  const { byNumber, byInvoiceId } = await creatorsForDocuments(db, missing.map((r) => String(r.reference || '')), ids);
  return rows.map((r) => {
    const own = clean(r.created_by);
    if (own) return { ...r, created_by: own };
    const id = invoiceIdFromNotes(r.notes);
    const who = (id != null ? byInvoiceId.get(id) : undefined) || byNumber.get(clean(r.reference)) || null;
    return { ...r, created_by: who };
  });
}

/** Stock movements: same rule, plus a sibling movement of the same document. */
export async function withMovementCreators<T extends Row>(db: D1Database, rows: T[]): Promise<T[]> {
  const missingRefs = [...new Set(rows.filter((r) => !clean(r.created_by)).map((r) => clean(r.reference)).filter(Boolean))];
  if (!missingRefs.length) return rows;
  const { byNumber } = await creatorsForDocuments(db, missingRefs);
  const unresolved = missingRefs.filter((ref) => !byNumber.has(ref));
  for (const part of chunks(unresolved)) {
    const ph = part.map(() => '?').join(', ');
    const sib = await safeAll(
      db,
      `SELECT reference, created_by FROM stock_movements
        WHERE reference IN (${ph}) AND created_by IS NOT NULL AND trim(created_by) <> ''
        ORDER BY id ASC`,
      part,
    );
    for (const r of sib) {
      const ref = clean(r.reference);
      if (ref && !byNumber.has(ref)) byNumber.set(ref, clean(r.created_by));
    }
  }
  return rows.map((r) => (clean(r.created_by) ? r : { ...r, created_by: byNumber.get(clean(r.reference)) || r.created_by }));
}
